    yield* TestClock.adjust("31 seconds");
    const timeout = yield* Fiber.join(fiber).pipe(Effect.flip);
    assert.strictEqual(Schema.is(SendblueDeliveryUncertainError)(timeout), true);
    assert.strictEqual(timeout.reason, "timeout");
  })
);

