import { Schema } from "effect";

const SendblueOperation = Schema.Literal("sendMessage");
const SafeMessage = Schema.NonEmptyString;

export class SendblueConfigError extends Schema.TaggedErrorClass<SendblueConfigError>()(
  "SendblueConfigError",
  { message: SafeMessage }
) {}

export class SendblueWebhookAuthenticationError extends Schema.TaggedErrorClass<SendblueWebhookAuthenticationError>()(
  "SendblueWebhookAuthenticationError",
  { message: SafeMessage }
) {}

export class SendblueWebhookSchemaError extends Schema.TaggedErrorClass<SendblueWebhookSchemaError>()(
  "SendblueWebhookSchemaError",
  { boundary: SafeMessage, message: SafeMessage }
) {}

export class SendblueSenderNotAllowedError extends Schema.TaggedErrorClass<SendblueSenderNotAllowedError>()(
  "SendblueSenderNotAllowedError",
  { message: SafeMessage }
) {}

export class SendblueRoutingError extends Schema.TaggedErrorClass<SendblueRoutingError>()(
  "SendblueRoutingError",
  { message: SafeMessage }
) {}

export class SendblueReplayStoreError extends Schema.TaggedErrorClass<SendblueReplayStoreError>()(
  "SendblueReplayStoreError",
  { message: SafeMessage }
) {}

export class SendblueRequestError extends Schema.TaggedErrorClass<SendblueRequestError>()(
  "SendblueRequestError",
  {
    message: SafeMessage,
    operation: SendblueOperation,
    reason: Schema.Literal("requestEncoding"),
  }
) {}

export class SendblueResponseError extends Schema.TaggedErrorClass<SendblueResponseError>()(
  "SendblueResponseError",
  {
    message: SafeMessage,
    operation: SendblueOperation,
    reason: Schema.Literals([
      "clientRejected",
      "malformedResponse",
      "rateLimited",
      "serverRejected",
      "unauthorized",
    ]),
    status: Schema.Int.check(Schema.isBetween({ maximum: 599, minimum: 100 })),
  }
) {}

export class SendblueDeliveryUncertainError extends Schema.TaggedErrorClass<SendblueDeliveryUncertainError>()(
  "SendblueDeliveryUncertainError",
  {
    message: SafeMessage,
    operation: SendblueOperation,
    reason: Schema.Literals(["timeout", "transport"]),
  }
) {}
import { Context, Effect, Layer, Match, Option, Redacted } from "effect";
import {
  HttpClient,
  HttpClientRequest,
  HttpClientResponse,
} from "effect/unstable/http";

import { SendblueConfigService } from "./config.js";
import {
  SendblueDeliveryUncertainError,
  SendblueRequestError,
  SendblueResponseError,
} from "./errors.js";
import { SendblueSendMessageInput, SendblueSendMessageSuccess } from "./schemas.js";
import type {
  SendblueSendMessageInput as SendblueSendMessageInputType,
  SendblueSendMessageSuccess as SendblueSendMessageSuccessType,
} from "./schemas.js";

export type SendblueClientError =
  | SendblueDeliveryUncertainError
  | SendblueRequestError
  | SendblueResponseError;

export interface SendblueClientShape {
  readonly sendMessage: (
    input: SendblueSendMessageInputType
  ) => Effect.Effect<SendblueSendMessageSuccessType, SendblueClientError>;
}

export class SendblueClient extends Context.Service<
  SendblueClient,
  SendblueClientShape
>()("@bundjil/agent/SendblueClient") {}

const executionTimeout = "30 seconds";

export const makeSendblueClient = Effect.gen(function* makeSendblueClientOperation() {
  const config = yield* SendblueConfigService;
  const client = yield* HttpClient.HttpClient;

  return SendblueClient.of({
    sendMessage: Effect.fn("SendblueClient.sendMessage")(function* (input) {
      const request = yield* HttpClientRequest.post(
        new URL("/api/send-message", config.apiBaseUrl).href
      ).pipe(
        HttpClientRequest.setHeader("sb-api-key-id", Redacted.value(config.apiKey)),
        HttpClientRequest.setHeader(
          "sb-api-secret-key",
          Redacted.value(config.apiSecret)
        ),
        HttpClientRequest.schemaBodyJson(SendblueSendMessageInput)(input),
        Effect.mapError(
          () =>
            new SendblueRequestError({
              message: "Unable to encode the Sendblue message request.",
              operation: "sendMessage",
              reason: "requestEncoding",
            })
        )
      );
      const response = yield* client.execute(request).pipe(
        Effect.mapError(
          () =>
            new SendblueDeliveryUncertainError({
              message: "The Sendblue delivery outcome is uncertain.",
              operation: "sendMessage",
              reason: "transport",
            })
        ),
        Effect.timeoutOption(executionTimeout),
        Effect.flatMap(
          Option.match({
            onNone: () =>
              Effect.fail(
                new SendblueDeliveryUncertainError({
                  message: "The Sendblue delivery request timed out.",
                  operation: "sendMessage",
                  reason: "timeout",
                })
              ),
            onSome: Effect.succeed,
          })
        )
      );

      if (response.status < 200 || response.status >= 300) {
        return yield* new SendblueResponseError({
          message: "Sendblue rejected the message request.",
          operation: "sendMessage",
          reason: Match.value(response.status).pipe(
            Match.when(401, () => "unauthorized" as const),
            Match.when(429, () => "rateLimited" as const),
            Match.when(
              (status) => status >= 500,
              () => "serverRejected" as const
            ),
            Match.orElse(() => "clientRejected" as const)
          ),
          status: response.status,
        });
      }

      return yield* HttpClientResponse.schemaBodyJson(
        SendblueSendMessageSuccess
      )(response).pipe(
        Effect.mapError(
          () =>
            new SendblueResponseError({
              message: "Sendblue returned an invalid message response.",
              operation: "sendMessage",
              reason: "malformedResponse",
              status: response.status,
            })
        )
      );
    }),
  });
}).pipe(Effect.withSpan("SendblueClientLive"));

export const SendblueClientLive = Layer.effect(SendblueClient, makeSendblueClient);
import { Config, Context, Effect, Layer, Option, Redacted, Schema } from "effect";

import { SendblueConfigError } from "./errors.js";
import {
  E164PhoneNumber,
  SendblueConfig,
  SendblueSenderIdentities,
} from "./schemas.js";
import type { SendblueConfig as SendblueConfigType } from "./schemas.js";

const apiKeyConfig = Config.redacted("BUNDJIL_SENDBLUE_API_KEY");
const apiSecretConfig = Config.redacted("BUNDJIL_SENDBLUE_API_SECRET");
const webhookSecretConfig = Config.redacted("BUNDJIL_SENDBLUE_WEBHOOK_SECRET");
const routingKeyConfig = Config.redacted("BUNDJIL_SENDBLUE_ROUTING_KEY");
const fromNumberConfig = Config.schema(E164PhoneNumber, "BUNDJIL_SENDBLUE_FROM_NUMBER");
const senderIdentitiesConfig = Config.redacted("BUNDJIL_SENDBLUE_SENDER_IDENTITIES");
const replayStoreUrlConfig = Config.redacted("BUNDJIL_SENDBLUE_REPLAY_STORE_URL");
const replayStoreTokenConfig = Config.redacted("BUNDJIL_SENDBLUE_REPLAY_STORE_TOKEN");
const replayStorePrefixConfig = Config.nonEmptyString("BUNDJIL_SENDBLUE_REPLAY_STORE_PREFIX");
const replayStoreTtlSecondsConfig = Config.schema(
  Schema.Int.check(Schema.isGreaterThan(0)),
  "BUNDJIL_SENDBLUE_REPLAY_STORE_TTL_SECONDS"
);
const replayStoreLeaseSecondsConfig = Config.schema(
  Schema.Int.check(Schema.isGreaterThan(0)),
  "BUNDJIL_SENDBLUE_REPLAY_STORE_LEASE_SECONDS"
);
const allowedServicesConfig = Config.schema(
  Schema.Array(Schema.Literals(["iMessage", "SMS", "RCS"])),
  "BUNDJIL_SENDBLUE_ALLOWED_SERVICES"
).pipe(Config.withDefault(["iMessage"]));
const testModeConfig = Config.option(
  Config.literal("true", "BUNDJIL_SENDBLUE_TEST_MODE")
);
const testApiBaseUrlConfig = Config.option(Config.url("BUNDJIL_SENDBLUE_TEST_API_BASE_URL"));

export class SendblueConfigService extends Context.Service<
  SendblueConfigService,
  SendblueConfigType
>()("@bundjil/agent/SendblueConfig") {}

export const loadSendblueConfig = Effect.gen(function* loadSendblueConfigFromProvider() {
  const values = yield* Effect.all({
    allowedServices: allowedServicesConfig,
    apiKey: apiKeyConfig,
    apiSecret: apiSecretConfig,
    fromNumber: fromNumberConfig,
    replayStoreLeaseSeconds: replayStoreLeaseSecondsConfig,
    replayStorePrefix: replayStorePrefixConfig,
    replayStoreToken: replayStoreTokenConfig,
    replayStoreTtlSeconds: replayStoreTtlSecondsConfig,
    replayStoreUrl: replayStoreUrlConfig,
    routingKey: routingKeyConfig,
    senderIdentities: senderIdentitiesConfig,
    testApiBaseUrl: testApiBaseUrlConfig,
    testMode: testModeConfig,
    webhookSecret: webhookSecretConfig,
  });
  const senderIdentities = yield* Schema.decodeUnknownEffect(
    Schema.fromJsonString(SendblueSenderIdentities)
  )(Redacted.value(values.senderIdentities));
  const apiBaseUrl = yield* Option.match(values.testApiBaseUrl, {
    onNone: () => Effect.succeed(new URL("https://api.sendblue.com")),
    onSome: (url) =>
      Option.match(values.testMode, {
        onNone: () =>
          Effect.fail(
            new SendblueConfigError({
              message: "The Sendblue test API URL requires test mode.",
            })
          ),
        onSome: () => Effect.succeed(url),
      }),
  });

  return yield* Schema.decodeUnknownEffect(SendblueConfig)({
    allowedServices: values.allowedServices,
    apiBaseUrl,
    apiKey: values.apiKey,
    apiSecret: values.apiSecret,
    fromNumber: values.fromNumber,
    replayStore: {
      leaseSeconds: values.replayStoreLeaseSeconds,
      prefix: values.replayStorePrefix,
      token: values.replayStoreToken,
      ttlSeconds: values.replayStoreTtlSeconds,
      url: values.replayStoreUrl,
    },
    routingKey: values.routingKey,
    senderIdentities,
    webhookSecret: values.webhookSecret,
  });
}).pipe(
  Effect.mapError(
    () =>
      new SendblueConfigError({
        message: "Unable to load Sendblue configuration.",
      })
  ),
  Effect.withSpan("SendblueConfig.load")
);

export const SendblueConfigLive = Layer.effect(
  SendblueConfigService,
  loadSendblueConfig
);


