import { Schema } from "effect";

export const E164PhoneNumber = Schema.String.check(
  Schema.isPattern(/^\+[1-9]\d{7,14}$/)
).pipe(Schema.brand("E164PhoneNumber"));
export type E164PhoneNumber = typeof E164PhoneNumber.Type;

export const SendblueMessageHandle = Schema.NonEmptyString.pipe(
  Schema.brand("SendblueMessageHandle")
);
export type SendblueMessageHandle = typeof SendblueMessageHandle.Type;

export const SendbluePrincipalId = Schema.NonEmptyString.pipe(
  Schema.brand("SendbluePrincipalId")
);
export type SendbluePrincipalId = typeof SendbluePrincipalId.Type;

export const SendblueConversationKey = Schema.NonEmptyString.pipe(
  Schema.brand("SendblueConversationKey")
);
export type SendblueConversationKey = typeof SendblueConversationKey.Type;

export const SendblueInboundClaimKey = Schema.NonEmptyString.pipe(
  Schema.brand("SendblueInboundClaimKey")
);
export type SendblueInboundClaimKey = typeof SendblueInboundClaimKey.Type;

export const SendblueOutboundClaimKey = Schema.NonEmptyString.pipe(
  Schema.brand("SendblueOutboundClaimKey")
);
export type SendblueOutboundClaimKey = typeof SendblueOutboundClaimKey.Type;

export const SendblueWebhookSecret = Schema.Redacted(Schema.NonEmptyString);
export type SendblueWebhookSecret = typeof SendblueWebhookSecret.Type;

export const SendblueSenderIdentity = Schema.Struct({
  phoneNumber: E164PhoneNumber,
  principalId: SendbluePrincipalId,
});
export type SendblueSenderIdentity = typeof SendblueSenderIdentity.Type;

export const SendblueSenderIdentities = Schema.Record(
  E164PhoneNumber,
  SendbluePrincipalId
);
export type SendblueSenderIdentities = typeof SendblueSenderIdentities.Type;

export const SendblueInboundMessage = Schema.Struct({
  content: Schema.String,
  from_number: E164PhoneNumber,
  group_id: Schema.optional(Schema.String),
  message_handle: SendblueMessageHandle,
  sendblue_number: E164PhoneNumber,
  service: Schema.Literals(["iMessage", "SMS", "RCS"]),
  status: Schema.String,
  to_number: E164PhoneNumber,
});
export type SendblueInboundMessage = typeof SendblueInboundMessage.Type;

export const SendblueIgnoredEvent = Schema.Struct({
  reason: Schema.Literals([
    "duplicate",
    "group",
    "media",
    "outbound",
    "senderNotAllowed",
    "serviceNotAllowed",
    "statusNotReceived",
  ]),
});
export type SendblueIgnoredEvent = typeof SendblueIgnoredEvent.Type;

export const SendblueChannelState = Schema.Struct({
  conversationKey: SendblueConversationKey,
  principalId: SendbluePrincipalId,
  sendblueNumber: E164PhoneNumber,
  senderNumber: E164PhoneNumber,
});
export type SendblueChannelState = typeof SendblueChannelState.Type;

export const SendblueSendMessageInput = Schema.Struct({
  content: Schema.NonEmptyString.check(Schema.isMaxLength(18_996)),
  from_number: E164PhoneNumber,
  number: E164PhoneNumber,
});
export type SendblueSendMessageInput = typeof SendblueSendMessageInput.Type;

export const SendblueSendMessageSuccess = Schema.Struct({
  message_handle: SendblueMessageHandle,
  status: Schema.Literals(["QUEUED", "SENT", "DELIVERED"]),
});
export type SendblueSendMessageSuccess = typeof SendblueSendMessageSuccess.Type;

export const ReplayClaimStatus = Schema.Literals([
  "claimed",
  "complete",
  "duplicate",
  "uncertain",
]);
export type ReplayClaimStatus = typeof ReplayClaimStatus.Type;

export const SendblueWebhookAcknowledgement = Schema.Struct({
  accepted: Schema.Boolean,
});
export type SendblueWebhookAcknowledgement =
  typeof SendblueWebhookAcknowledgement.Type;

export const SendblueProofResult = Schema.Struct({
  accepted: Schema.Boolean,
  status: Schema.Int.check(Schema.isBetween({ maximum: 599, minimum: 100 })),
});
export type SendblueProofResult = typeof SendblueProofResult.Type;

export const SendblueConfig = Schema.Struct({
  allowedServices: Schema.Array(Schema.Literals(["iMessage", "SMS", "RCS"])),
  apiBaseUrl: Schema.URL,
  apiKey: Schema.Redacted(Schema.NonEmptyString),
  apiSecret: Schema.Redacted(Schema.NonEmptyString),
  fromNumber: E164PhoneNumber,
  replayStore: Schema.Struct({
    leaseSeconds: Schema.Int.check(Schema.isGreaterThan(0)),
    prefix: Schema.NonEmptyString,
    token: Schema.Redacted(Schema.NonEmptyString),
    ttlSeconds: Schema.Int.check(Schema.isGreaterThan(0)),
    url: Schema.Redacted(Schema.NonEmptyString),
  }),
  routingKey: Schema.Redacted(Schema.NonEmptyString),
  senderIdentities: SendblueSenderIdentities,
  webhookSecret: SendblueWebhookSecret,
});
export type SendblueConfig = typeof SendblueConfig.Type;
import { Context, Effect, Layer, Match, Option, Redacted } from "effect";
import {
  HttpClient,
  HttpClientRequest,
  HttpClientResponse,
} from "effect/unstable/http";

import { SendblueConfigService } from "./config.js";
import {
  SendblueDeliveryUncertainError,
  SendblueRequestError,
  SendblueResponseError,
} from "./errors.js";
import {
  SendblueSendMessageInput,
  SendblueSendMessageSuccess,
} from "./schemas.js";
import type {
  SendblueSendMessageInput as SendblueSendMessageInputType,
  SendblueSendMessageSuccess as SendblueSendMessageSuccessType,
} from "./schemas.js";

export type SendblueClientError =
  | SendblueDeliveryUncertainError
  | SendblueRequestError
  | SendblueResponseError;

export interface SendblueClientShape {
  readonly sendMessage: (
    input: SendblueSendMessageInputType
  ) => Effect.Effect<SendblueSendMessageSuccessType, SendblueClientError>;
}

export class SendblueClient extends Context.Service<
  SendblueClient,
  SendblueClientShape
>()("@bundjil/agent/SendblueClient") {}

const executionTimeout = "30 seconds";

export const makeSendblueClient = Effect.gen(
  function* makeSendblueClientOperation() {
    const config = yield* SendblueConfigService;
    const client = yield* HttpClient.HttpClient;

    return SendblueClient.of({
      sendMessage: Effect.fn("SendblueClient.sendMessage")(function* (input) {
        const request = yield* HttpClientRequest.post(
          new URL("/api/send-message", config.apiBaseUrl).href
        ).pipe(
          HttpClientRequest.setHeader(
            "sb-api-key-id",
            Redacted.value(config.apiKey)
          ),
          HttpClientRequest.setHeader(
            "sb-api-secret-key",
            Redacted.value(config.apiSecret)
          ),
          HttpClientRequest.schemaBodyJson(SendblueSendMessageInput)(input),
          Effect.mapError(
            () =>
              new SendblueRequestError({
                message: "Unable to encode the Sendblue message request.",
                operation: "sendMessage",
                reason: "requestEncoding",
              })
          )
        );
        const response = yield* client.execute(request).pipe(
          Effect.mapError(
            () =>
              new SendblueDeliveryUncertainError({
                message: "The Sendblue delivery outcome is uncertain.",
                operation: "sendMessage",
                reason: "transport",
              })
          ),
          Effect.timeoutOption(executionTimeout),
          Effect.flatMap(
            Option.match({
              onNone: () =>
                Effect.fail(
                  new SendblueDeliveryUncertainError({
                    message: "The Sendblue delivery request timed out.",
                    operation: "sendMessage",
                    reason: "timeout",
                  })
                ),
              onSome: Effect.succeed,
            })
          )
        );

        if (response.status < 200 || response.status >= 300) {
          return yield* new SendblueResponseError({
            message: "Sendblue rejected the message request.",
            operation: "sendMessage",
            reason: Match.value(response.status).pipe(
              Match.when(401, () => "unauthorized" as const),
              Match.when(429, () => "rateLimited" as const),
              Match.when(
                (status) => status >= 500,
                () => "serverRejected" as const
              ),
              Match.orElse(() => "clientRejected" as const)
            ),
            status: response.status,
          });
        }

        return yield* HttpClientResponse.schemaBodyJson(
          SendblueSendMessageSuccess
        )(response).pipe(
          Effect.mapError(
            () =>
              new SendblueResponseError({
                message: "Sendblue returned an invalid message response.",
                operation: "sendMessage",
                reason: "malformedResponse",
                status: response.status,
              })
          )
        );
      }),
    });
  }
).pipe(Effect.withSpan("SendblueClientLive"));

export const SendblueClientLive = Layer.effect(
  SendblueClient,
  makeSendblueClient
);
import { assert, it } from "@effect/vitest";
import { Deferred, Effect, Fiber, Layer, Redacted, Ref, Schema } from "effect";
import { TestClock } from "effect/testing";
import {
  HttpClient,
  HttpClientError,
  HttpClientRequest,
  HttpClientResponse,
} from "effect/unstable/http";

import {
  SendblueClient,
  SendblueClientLive,
} from "../agent/sendblue/client.service.js";
import { SendblueConfigService } from "../agent/sendblue/config.js";
import {
  SendblueDeliveryUncertainError,
  SendblueResponseError,
} from "../agent/sendblue/errors.js";
import { SendblueClientMemory } from "../agent/sendblue/memory.layer.js";
import {
  SendblueConfig,
  SendblueSenderIdentities,
  SendblueSendMessageInput,
  SendblueSendMessageSuccess,
} from "../agent/sendblue/schemas.js";

const senderIdentities = Schema.decodeUnknownSync(SendblueSenderIdentities)({
  "+14155550100": "owner",
});

const config = Schema.decodeUnknownSync(SendblueConfig)({
  allowedServices: ["iMessage"],
  apiBaseUrl: new URL("https://api.sendblue.test"),
  apiKey: Redacted.make("test-api-key"),
  apiSecret: Redacted.make("test-api-secret"),
  fromNumber: "+13472760577",
  replayStore: {
    leaseSeconds: 60,
    prefix: "sendblue:test",
    token: Redacted.make("test-replay-token"),
    ttlSeconds: 86_400,
    url: Redacted.make("https://example.test/redis"),
  },
  routingKey: Redacted.make("test-routing-key"),
  senderIdentities,
  webhookSecret: Redacted.make("test-webhook-secret"),
});

const input = Schema.decodeUnknownSync(SendblueSendMessageInput)({
  content: "A concise reply.",
  from_number: "+13472760577",
  number: "+14155550100",
});

const encodeSuccess = Schema.encodeSync(
  Schema.fromJsonString(SendblueSendMessageSuccess)
);

it.effect("provides deterministic unseeded memory client failures", () =>
  Effect.gen(function* testMemoryClient() {
    const error = yield* Effect.gen(function* sendWithMemoryClient() {
      const sendblue = yield* SendblueClient;
      return yield* sendblue.sendMessage(input);
    }).pipe(Effect.provide(SendblueClientMemory()), Effect.flip);

    assert.strictEqual(Schema.is(SendblueDeliveryUncertainError)(error), true);
    assert.strictEqual(error.reason, "transport");
  })
);

it.effect(
  "sends schema-encoded requests with the Sendblue authentication headers",
  () =>
    Effect.gen(function* testSendMessageRequest() {
      const captured = yield* Ref.make<
        Readonly<{
          body: string;
          keyId: string | null;
          secretKey: string | null;
        }>
      >({ body: "", keyId: null, secretKey: null });
      const client = HttpClient.make((request) =>
        Effect.gen(function* captureSendMessageRequest() {
          const webRequest = yield* HttpClientRequest.toWeb(request).pipe(
            Effect.orDie
          );
          const body = yield* Effect.promise(() => webRequest.text());
          yield* Ref.set(captured, {
            body,
            keyId: webRequest.headers.get("sb-api-key-id"),
            secretKey: webRequest.headers.get("sb-api-secret-key"),
          });
          return HttpClientResponse.fromWeb(
            request,
            new Response(
              encodeSuccess(
                Schema.decodeUnknownSync(SendblueSendMessageSuccess)({
                  message_handle: "msg_test_handle",
                  status: "QUEUED",
                })
              ),
              { headers: { "content-type": "application/json" }, status: 202 }
            )
          );
        })
      );
      const layer = SendblueClientLive.pipe(
        Layer.provideMerge(
          Layer.merge(
            Layer.succeed(HttpClient.HttpClient, client),
            Layer.succeed(SendblueConfigService, config)
          )
        )
      );
      yield* Effect.gen(function* executeSendMessage() {
        const sendblue = yield* SendblueClient;
        const response = yield* sendblue.sendMessage(input);
        const request = yield* Ref.get(captured);
        const decodedBody = yield* Schema.decodeUnknownEffect(
          Schema.fromJsonString(SendblueSendMessageInput)
        )(request.body).pipe(Effect.orDie);

        assert.notStrictEqual(request.keyId, null);
        assert.notStrictEqual(request.secretKey, null);
        assert.strictEqual(decodedBody.number, input.number);
        assert.strictEqual(decodedBody.from_number, input.from_number);
        assert.strictEqual(response.status, "QUEUED");
        assert.strictEqual(response.message_handle, "msg_test_handle");
      }).pipe(Effect.provide(layer));
    })
);

it.effect(
  "classifies provider status and malformed responses without provider body leakage",
  () =>
    Effect.gen(function* testResponseFailures() {
      const makeLayer = (status: number, body: string) =>
        SendblueClientLive.pipe(
          Layer.provideMerge(
            Layer.merge(
              Layer.succeed(
                HttpClient.HttpClient,
                HttpClient.make((request) =>
                  Effect.succeed(
                    HttpClientResponse.fromWeb(
                      request,
                      new Response(body, {
                        headers: { "content-type": "application/json" },
                        status,
                      })
                    )
                  )
                )
              ),
              Layer.succeed(SendblueConfigService, config)
            )
          )
        );
      const unauthorized = yield* Effect.gen(function* sendUnauthorized() {
        const sendblue = yield* SendblueClient;
        return yield* sendblue.sendMessage(input);
      }).pipe(
        Effect.provide(makeLayer(401, '{"message":"provider detail"}')),
        Effect.flip
      );
      assert.strictEqual(Schema.is(SendblueResponseError)(unauthorized), true);
      assert.strictEqual(unauthorized.reason, "unauthorized");
      assert.notInclude(String(unauthorized), "provider detail");
      assert.notInclude(String(unauthorized), "test-api-key");
      assert.notInclude(String(unauthorized), "test-api-secret");
      assert.notInclude(String(unauthorized), "+14155550100");
      assert.notInclude(String(unauthorized), "A concise reply.");

      const rateLimited = yield* Effect.gen(function* sendRateLimited() {
        const sendblue = yield* SendblueClient;
        return yield* sendblue.sendMessage(input);
      }).pipe(Effect.provide(makeLayer(429, "{}")), Effect.flip);
      assert.strictEqual(rateLimited.reason, "rateLimited");

      const malformed = yield* Effect.gen(function* sendMalformedResponse() {
        const sendblue = yield* SendblueClient;
        return yield* sendblue.sendMessage(input);
      }).pipe(Effect.provide(makeLayer(200, "{}")), Effect.flip);
      assert.strictEqual(malformed.reason, "malformedResponse");
    })
);

it.effect(
  "marks transport and timeout outcomes uncertain without automatic retries",
  () =>
    Effect.gen(function* testUncertainOutcomes() {
      const transportLayer = SendblueClientLive.pipe(
        Layer.provideMerge(
          Layer.merge(
            Layer.succeed(
              HttpClient.HttpClient,
              HttpClient.make((request) =>
                Effect.fail(
                  new HttpClientError.HttpClientError({
                    reason: new HttpClientError.TransportError({ request }),
                  })
                )
              )
            ),
            Layer.succeed(SendblueConfigService, config)
          )
        )
      );
      const transport = yield* Effect.gen(function* sendTransportFailure() {
        const sendblue = yield* SendblueClient;
