                BUNDJIL_SENDBLUE_TEST_API_BASE_URL: "http://127.0.0.1:8787",
              },
            })
          )
        ),
        Effect.flip
      );
      assert.strictEqual(
        Schema.is(SendblueConfigError)(unguardedOverrideError),
        true
      );

      const testConfig = yield* loadSendblueConfig.pipe(
