                BUNDJIL_SENDBLUE_TEST_API_BASE_URL: "http://127.0.0.1:8787",
                BUNDJIL_SENDBLUE_TEST_MODE: "true",
              },
            })
          )
        )
      );
      assert.strictEqual(testConfig.apiBaseUrl.href, "http://127.0.0.1:8787/");
    })
);


